'use strict';
const KEY='forex-demo-v01';
const initial=()=>({active:false,risk:1,trades:[],history:[],events:['Panel iniciado. OANDA no está conectado.']});
let state=initial();
try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&Number.isFinite(s.risk)&&s.risk>=.1&&s.risk<=2&&Array.isArray(s.trades)&&s.trades.length<=2&&s.trades.every(t=>Number.isInteger(t.units)&&t.units>0&&t.units<=10000&&Number.isFinite(t.risk)&&t.risk>0)&&s.trades.reduce((a,t)=>a+t.risk,0)<=2&&Array.isArray(s.history)&&s.history.length<=1000&&s.history.every(t=>Number.isFinite(t.profit)&&Number.isInteger(t.units)&&typeof t.time==='string')&&Array.isArray(s.events)&&s.events.every(t=>typeof t==='string'))state={...s,active:false};}catch{}
const $=id=>document.getElementById(id);
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{$('notice').textContent='El navegador no permite guardar datos locales.';}}
function log(text){state.events.unshift(new Date().toLocaleTimeString('es')+' · '+text);state.events=state.events.slice(0,30);save();render();}
function notice(text){$('notice').textContent=text;}
function go(tab){document.querySelectorAll('.tab').forEach(e=>e.hidden=e.id!==tab);document.querySelectorAll('[data-tab]').forEach(e=>e.classList.toggle('selected',e.dataset.tab===tab));$('title').textContent={panel:'Panel de control',operaciones:'Operaciones',estrategia:'Estrategia',historial:'Historial',configuracion:'Configuración'}[tab];if(tab==='panel')draw();}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>go(b.dataset.tab));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('settings').onclick=()=>go('configuracion');
function row(body,values){const tr=document.createElement('tr');for(const value of values){const td=document.createElement('td');td.textContent=value;tr.append(td);}body.append(tr);}
function render(){const profit=state.history.reduce((a,t)=>a+t.profit,0);$('balance').textContent=money(1000+profit);$('profit').textContent=money(profit);$('risk').textContent=state.trades.reduce((a,t)=>a+t.risk,0).toFixed(1)+'% / 2%';$('count').textContent=state.trades.length+' / 2';$('status').textContent=state.active?'● Controles de demo activos':'● Simulación pausada';$('toggle').textContent=state.active?'Pausar entradas':'Activar controles de demo';$('risk-label').textContent=state.risk+'%';$('risk-input').value=state.risk;$('trades').replaceChildren();for(const t of state.trades)row($('trades'),['EUR/USD','Compra',t.units,'1.09500','1.09300','1.09900',money(t.units*.00248)]);if(!state.trades.length)row($('trades'),['Sin posiciones. Puedes añadir un ejemplo desde los controles.']);$('history').replaceChildren();for(const t of state.history)row($('history'),[t.time,'EUR/USD',t.units,money(t.profit)]);if(!state.history.length)row($('history'),['Todavía no hay operaciones de ejemplo cerradas.']);$('activity').replaceChildren();for(const e of state.events){const li=document.createElement('li');li.textContent=e;$('activity').append(li);}}
$('toggle').onclick=()=>{state.active=!state.active;notice('Cambio aplicado solo a esta simulación local.');log(state.active?'Controles activados; no se ejecutan operaciones automáticamente.':'Entradas pausadas; las posiciones se conservan.');};
$('example').onclick=()=>{if(!state.active)return notice('Activa los controles de demo para añadir un ejemplo.');if(state.trades.length>=2)return notice('Máximo dos posiciones de ejemplo.');const used=state.trades.reduce((a,t)=>a+t.risk,0);if(used+state.risk>2+1e-9)return notice('La operación excede el presupuesto de riesgo abierto del 2%.');state.trades.push({units:Math.floor(1000*state.risk/100/.002),risk:state.risk});notice('Ejemplo añadido a un precio fijo. P/L ilustrativo; no incluye costos.');log('Operación ficticia EUR/USD añadida.');};
$('close').onclick=()=>{if(!state.trades.length)return notice('No hay posiciones abiertas.');if(!confirm('¿Cerrar todas las posiciones ficticias al precio de ejemplo 1.09748?'))return;for(const t of state.trades)state.history.unshift({units:t.units,profit:Math.round(t.units*.00248*100)/100,time:new Date().toISOString()});state.history=state.history.slice(0,1000);state.trades=[];notice('Cierre ficticio registrado. OANDA no recibió órdenes.');log('Posiciones de ejemplo cerradas.');};
$('config').onsubmit=e=>{e.preventDefault();const risk=Number($('risk-input').value);if(!Number.isFinite(risk)||risk<.1||risk>2)return notice('El riesgo debe estar entre 0.1% y 2%.');state.risk=risk;log('Riesgo de nuevos ejemplos actualizado a '+risk+'%.');notice('Configuración guardada en este navegador.');};
$('reset').onclick=()=>{if(confirm('¿Borrar la configuración y el historial de ejemplo de este navegador?')){state=initial();save();render();notice('Simulación reiniciada.');}};
$('export').onclick=()=>{const rows=['fecha,par,unidades,resultado_ilustrativo_usd',...state.history.map(t=>[JSON.stringify(t.time),'EUR_USD',t.units,t.profit].join(','))];const url=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='historial-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function draw(){const c=$('chart'),rect=c.getBoundingClientRect();if(!rect.width)return;const dpr=window.devicePixelRatio||1,w=rect.width,h=340;c.width=w*dpr;c.height=h*dpr;const x=c.getContext('2d');x.scale(dpr,dpr);const margin=68,pw=w-margin;const y=p=>h-30-(p-1.0915)/.0095*(h-55);x.font='11px system-ui';for(let p=1.092;p<=1.101;p+=.001){x.strokeStyle='#20354a';x.beginPath();x.moveTo(0,y(p));x.lineTo(pw,y(p));x.stroke();x.fillStyle='#99afc6';x.fillText(p.toFixed(5),pw+8,y(p)+4);}let prev=1.0944;for(let i=0;i<80;i++){const close=1.0944+i*.000047+Math.sin(i*.23)*.0007+Math.sin(i*1.7)*.00013;const open=prev,high=Math.max(open,close)+.00016,low=Math.min(open,close)-.00014,px=8+i*(pw-18)/80;x.strokeStyle=close>=open?'#23c6ad':'#e96175';x.fillStyle=x.strokeStyle;x.beginPath();x.moveTo(px,y(high));x.lineTo(px,y(low));x.stroke();x.fillRect(px-2,y(Math.max(open,close)),4,Math.max(2,Math.abs(y(open)-y(close))));prev=close;}for(const [p,label,color]of[[1.099,'Objetivo 1.09900','#22d3a3'],[1.095,'Entrada 1.09500','#53b9ff'],[1.093,'Stop 1.09300','#fa7180']]){x.strokeStyle=color;x.setLineDash([4,4]);x.beginPath();x.moveTo(0,y(p));x.lineTo(pw,y(p));x.stroke();x.setLineDash([]);x.fillStyle=color;x.fillText(label,Math.max(5,pw-125),y(p)-8);}x.fillStyle='#829ab2';x.fillText('Serie ilustrativa · sin actualización automática',10,h-8);}
window.addEventListener('resize',draw);render();draw();
